#!/usr/bin/env python3
"""Restore reviewed v1.7.1 source delta and local QA; no app binaries or secrets."""
import base64,hashlib,json,zlib
from pathlib import Path
DATA = """"""
raw=zlib.decompress(base64.b64decode(DATA))
assert hashlib.sha256(raw).hexdigest()=="4a5f0d7ecee45d8ae7af64888bc2382f1864f4f3963798386ef55a23c5d61c44"
files=json.loads(raw)
assert set(files)=={"repair171.py","finalize171.py","reviewed171.json"}
root=Path(__file__).resolve().parent/'generated'
root.mkdir(exist_ok=True)
for name,text in files.items():
    assert Path(name).name==name
    (root/name).write_text(text,encoding='utf-8')
print("Restored hash-checked hotfix delta and local QA; no original APK/APKS, photos or signing keys.")
